sealed class RustComponentsException: kotlin.Exception() {

    class Core(

        val v1: kotlin.String
        ) : RustComponentsException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class Sync(

        val v1: kotlin.String
        ) : RustComponentsException() {
        override val message
            get() = "v1=${ v1 }"
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RustComponentsException> {
        override fun lift(error_buf: RustBuffer.ByValue): RustComponentsException = FfiConverterTypeRustComponentsError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeRustComponentsError : FfiConverterRustBuffer<RustComponentsException> {
    override fun read(buf: ByteBuffer): RustComponentsException {


        return when(buf.getInt()) {
            1 -> RustComponentsException.Core(
                FfiConverterString.read(buf),
                )
            2 -> RustComponentsException.Sync(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RustComponentsException): ULong {
        return when(value) {
            is RustComponentsException.Core -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is RustComponentsException.Sync -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: RustComponentsException, buf: ByteBuffer) {
        when(value) {
            is RustComponentsException.Core -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is RustComponentsException.Sync -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalInt: FfiConverterRustBuffer<kotlin.Int?> {
    override fun read(buf: ByteBuffer): kotlin.Int? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterInt.read(buf)
    }

    override fun allocationSize(value: kotlin.Int?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Int?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterInt.write(value, buf)
        }
    }
}




